def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    mod = 1_000_000_007

    children = [{}]
    failure = [0]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            if char not in children[state]:
                children[state][char] = len(children)
                children.append({})
                failure.append(0)
                terminal.append(False)
            state = children[state][char]
        terminal[state] = True

    from collections import deque

    queue = deque()
    for char in alphabet:
        if char in children[0]:
            queue.append(children[0][char])
        else:
            children[0][char] = 0

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]
        for char in alphabet:
            if char in children[state]:
                nxt = children[state][char]
                failure[nxt] = children[failure[state]][char]
                queue.append(nxt)
            else:
                children[state][char] = children[failure[state]][char]

    safe = [state for state in range(len(children)) if not terminal[state]]
    index = {state: i for i, state in enumerate(safe)}
    size = len(safe)

    matrix = [[0] * size for _ in range(size)]
    for state in safe:
        row = matrix[index[state]]
        for char in alphabet:
            nxt = children[state][char]
            if not terminal[nxt]:
                row[index[nxt]] += 1

    vector = [0] * size
    vector[index[0]] = 1

    def multiply_matrices(a, b):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if a[i][k]:
                    value = a[i][k]
                    for j in range(size):
                        result[i][j] += value * b[k][j]
            for j in range(size):
                result[i][j] %= mod
        return result

    while n:
        if n & 1:
            result = [0] * size
            for i in range(size):
                if vector[i]:
                    for j in range(size):
                        result[j] += vector[i] * matrix[i][j]
            vector = [value % mod for value in result]
        n >>= 1
        if n:
            matrix = multiply_matrices(matrix, matrix)

    return sum(vector) % mod
